               <div *ngIf="productFormGroup.controls.name.errors">Name is required</div>
            </div>
 </div> -->
 <div class="form-group">
  <label>Price</label>
  <input type="text" class="form-control" placeholder="Price" formControlName="price">
 </div>
 <div class="form-group">
  <label>Quantity</label>
  <input type="text" class="form-control" placeholder="Quantity" formControlName="quantity">
</div>
   <!-- <div class="form-group">
      <label>selected</label>
      <input type="text" class="form-control" placeholder="selected" formControlName="selected">
   </div> -->
    <div class="form-group">
      <label>Selected</label>
      <input type="checkbox" class="form-check" formControlName="selected">
    </div>
    <div class="form-group">
      <label>Available</label>
      <input type="checkbox" class="form-check" formControlName="available">
    </div>
    <button class="btn btn-success" (click)="onSaveProduct()">Save</button>
</form>
</div>
